package com.whatsaas.automation.engine;
import com.fasterxml.jackson.databind.*; import com.whatsaas.automation.domain.WorkflowExecution; import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.net.URI;
@Component public class WebhookNodeProcessor implements WorkflowNodeProcessor{private final RestClient client;private final ObjectMapper mapper;public WebhookNodeProcessor(RestClient.Builder b,ObjectMapper m){client=b.build();mapper=m;}public String type(){return "webhook";}public NodeResult process(WorkflowExecution e,JsonNode n,JsonNode c)throws Exception{String url=n.path("data").path("url").asText();URI uri=URI.create(url);if(!("https".equals(uri.getScheme())||"http".equals(uri.getScheme())))throw new IllegalArgumentException("Webhook URL must be HTTP(S).");String method=n.path("data").path("method").asText("POST");String body=n.path("data").has("body")?mapper.writeValueAsString(n.path("data").path("body")):mapper.writeValueAsString(c);String out="GET".equalsIgnoreCase(method)?client.get().uri(uri).retrieve().body(String.class):client.post().uri(uri).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(String.class);return NodeResult.next(mapper.writeValueAsString(mapper.createObjectNode().put("response",out==null?"":out)));}}
